const posts = pm.response.json();

pm.test("Status is 200", () => {
    pm.response.to.have.status(200);
});

pm.test("Response is an array of 100 posts", () => {
    pm.expect(posts).to.be.an("array").with.lengthOf(100);
});

pm.test("Every post has the expected properties", () => {
    posts.forEach(post => {
        pm.expect(post).to.have.all.keys("userId", "id", "title", "body");
    });
});

pm.test("All ids are unique numbers", () => {
    const ids = posts.map(p => p.id);
    ids.forEach(id => pm.expect(id).to.be.a("number"));
    pm.expect(new Set(ids).size).to.equal(ids.length);
});

const user = pm.response.json();

pm.test("Status is 200", () => {
    pm.response.to.have.status(200);
});

pm.test("User has the expected top-level properties", () => {
    pm.expect(user).to.have.all.keys(
        "id", "name", "username", "email", "address", "phone", "website", "company"
    );
});

pm.test("id is 1 and name is a non-empty string", () => {
    pm.expect(user.id).to.equal(1);
    pm.expect(user.name).to.be.a("string").and.not.empty;
});

pm.test("Email looks valid", () => {
    pm.expect(user.email).to.match(/^\S+@\S+\.\S+$/);
});

pm.test("Address has nested geo coordinates", () => {
    pm.expect(user.address).to.have.all.keys("street", "suite", "city", "zipcode", "geo");
    pm.expect(user.address.geo).to.have.property("lat");
    pm.expect(user.address.geo).to.have.property("lng");
});

pm.test("Company name exists", () => {
    pm.expect(user.company.name).to.be.a("string").and.not.empty;
});

